class Solution { private fun solve(slices:IntArray,start:Int,end:Int,picks:Int):Int{val length=end-start+1;val negative=-1_000_000_000;val dp=Array(length+1){IntArray(picks+1){negative}};for(i in 0..length)dp[i][0]=0;for(i in 1..length)for(chosen in 1..picks){dp[i][chosen]=dp[i-1][chosen];val previous=dp[maxOf(0,i-2)][chosen-1];if(previous!=negative)dp[i][chosen]=maxOf(dp[i][chosen],previous+slices[start+i-1])};return dp[length][picks]};fun maxSizeSlices(slices:IntArray):Int{val picks=slices.size/3;return maxOf(solve(slices,0,slices.size-2,picks),solve(slices,1,slices.size-1,picks))} }
